+            throw new IOException("Unclosed object or array found");
+        }
+        if (writeLineFeedAtEnd) {
+            flush();
+            // Bypass generator to always write the line feed
+            getLowLevelGenerator().writeRaw(LF);
+        }
+        generator.close();
+    }
+
+    @Override
+    public boolean isClosed() {
+        return generator.isClosed();
+    }
+}
