+                break;
+            case END_OBJECT:
+                writeEndObject();
+                break;
+            case START_ARRAY:
+                writeStartArray();
+                break;
+            case END_ARRAY:
+                writeEndArray();
+                break;
+            case FIELD_NAME:
+                writeFieldName(parser.currentName());
+                break;
+            case VALUE_STRING:
+                if (parser.hasTextCharacters()) {
